import json,itertools
artifact={"table":[{"when":{"wear":"worn"},"bin":"stabilize"},{"when":{"carrier":"wax"},"bin":"cold"},{"when":{"marked":True},"bin":"digitize"},{"when":{},"bin":"shelf"}],"routed":["cold","stabilize","digitize","shelf"],"witness":{"input":{"request":{"wear":"worn","carrier":"wax","marked":False}},"expected":"stabilize"}}
payload=json.dumps(artifact,separators=(",",":"))
a=json.loads(payload)
def route(inp):
    r=inp["request"]
    return next(row["bin"] for row in a["table"] if all(r[k]==v for k,v in row["when"].items()))
def expected(inp):
    r=inp["request"]
    return "stabilize" if r["wear"]=="worn" else "cold" if r["carrier"]=="wax" else "digitize" if r["marked"] else "shelf"
def faulty(inp):
    return "cold" if inp["request"]["carrier"]=="wax" else expected(inp)
legal={"wear":["worn","sound"],"carrier":["wax","film","disc"],"marked":[False,True]}
assert set(a)=={"table","routed","witness"}
for row in a["table"]:
    assert set(row)=={"when","bin"} and row["bin"] in {"stabilize","cold","digitize","shelf"}
    assert all(k in legal and type(v)==type(legal[k][0]) and v in legal[k] for k,v in row["when"].items())
for wear,carrier,marked in itertools.product(*legal.values()):
    inp={"request":dict(wear=wear,carrier=carrier,marked=marked)}
    assert route(inp)==expected(inp)
inputs=json.loads('[{"request":{"wear":"sound","carrier":"wax","marked":true}},{"request":{"wear":"worn","carrier":"film","marked":false}},{"request":{"wear":"sound","carrier":"disc","marked":true}},{"request":{"wear":"sound","carrier":"film","marked":false}}]')
assert a["routed"]==[route(i) for i in inputs]==[expected(i) for i in inputs]
w=a["witness"]
assert set(w)=={"input","expected"} and set(w["input"])=={"request"}
assert set(w["input"]["request"])==set(legal)
assert all(type(v)==type(legal[k][0]) and v in legal[k] for k,v in w["input"]["request"].items())
assert route(w["input"])==expected(w["input"])==w["expected"]
assert faulty(w["input"])!=w["expected"]
print(payload)
print("PASS: all 12 inputs, supplied outputs, schema, and faulty-sorter witness checked.")

